import React, { createContext, useContext, useState, useEffect } from 'react';
import { getData, saveData } from '../services/localStorageService';
import { hotels as sampleHotels } from '../data/sampleData';
import { generateId } from '../utils/helpers';

const HotelContext = createContext();

export const HotelProvider = ({ children }) => {
  const [hotels, setHotels] = useState([]);

  useEffect(() => {
    const stored = getData('hotels');
    if (stored.length === 0) {
      saveData('hotels', sampleHotels);
      setHotels(sampleHotels);
    } else {
      setHotels(stored);
    }
  }, []);

  const addHotel = (hotel) => {
    const newHotel = { ...hotel, id: generateId() };
    const updated = [...hotels, newHotel];
    saveData('hotels', updated);
    setHotels(updated);
    return newHotel;
  };

  const updateHotel = (id, updates) => {
    const updated = hotels.map(h => h.id === id ? { ...h, ...updates } : h);
    saveData('hotels', updated);
    setHotels(updated);
  };

  const deleteHotel = (id) => {
    const updated = hotels.filter(h => h.id !== id);
    saveData('hotels', updated);
    setHotels(updated);
  };

  const getHotelById = (id) => hotels.find(h => h.id === id);

  return (
    <HotelContext.Provider value={{ hotels, addHotel, updateHotel, deleteHotel, getHotelById }}>
      {children}
    </HotelContext.Provider>
  );
};

export const useHotels = () => useContext(HotelContext);
export default HotelContext;
